"""Install the workbook editor API and latest checked browser build together.

Prepare by default; --apply activates the API update and then the web-only update.
Existing database, custom image features, server pairing, OCR/search and original
workbooks are preserved. Each step prints its own rollback path.
"""

import base64
import gzip
import json
import os
import runpy
import tempfile
from pathlib import Path

PAYLOAD = ''  # noqa: E501 - frozen reviewed installers


def main():
    root = Path(tempfile.mkdtemp(prefix="dhanz-office-preview-", dir=Path.home()))
    root.chmod(0o700)
    sources = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    for name in ("install_spreadsheet_tools.py", "install_chat_preview.py"):
        target = root / name
        target.write_text(sources[name])
        target.chmod(0o600)
        runpy.run_path(str(target), run_name="__main__")
    print("Office preview API and browser setup completed. Refresh the browser or installed Android web app.")


if __name__ == "__main__":
    os.umask(0o077)
    main()
